function h(string $v): string { return htmlspecialchars($v,ENT_QUOTES,'UTF-8'); }
$message='';$error=false;
$user=oyya_current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $a=(string)($_POST['action']??'');
 if($a==='register'){[$ok,$message]=oyya_register($_POST);$error=!$ok;if($ok){header('Location:/');exit;}}
 elseif($a==='login'){[$ok,$message]=oyya_login($_POST);$error=!$ok;if($ok){header('Location:/');exit;}}
 elseif($a==='logout'){oyya_logout();header('Location:/');exit;}
 else{
  $user=oyya_current_user(); if(!$user){header('Location:/');exit;} $uid=(string)$user['id'];
  if($a==='post'){[$ok,$message]=oyya_create_post($uid,$_POST);$error=!$ok;}
  elseif($a==='like')oyya_toggle_like($uid,(string)$_POST['post_id']);
  elseif($a==='comment'){[$ok,$message]=oyya_add_comment($uid,(string)$_POST['post_id'],(string)($_POST['text']??''));$error=!$ok;}
  elseif($a==='follow')oyya_toggle_follow($uid,(string)$_POST['target_id']);
  elseif($a==='save')oyya_toggle_save($uid,(string)$_POST['post_id']);
  elseif($a==='profile'){[$ok,$message]=oyya_profile_update($uid,$_POST);$error=!$ok;}
  elseif($a==='entity'){[$ok,$message]=oyya_create_entity($uid,$_POST);$error=!$ok;}
  elseif($a==='membership')oyya_toggle_membership($uid,(string)$_POST['entity_id']);
  elseif($a==='message'){[$ok,$message]=oyya_send_message($uid,(string)$_POST['to_id'],(string)($_POST['text']??''));$error=!$ok;}
  $goto=preg_replace('/[^a-z_]/','',(string)($_POST['return_view']??'feed'))?:'feed';header('Location:/?view='.$goto);exit;
 }
}
$user=oyya_current_user();$users=oyya_users();$usersCount=count($users);$remaining=max(0,OYYA_MAX_USERS-$usersCount);$view=(string)($_GET['view']??'feed');
