const rb=document.getElementById('radioToggle');if(rb){const dock=document.getElementById('audioDock'),meta=document.getElementById('audioMeta'),vol=document.getElementById('volume'),adhan=document.getElementById('adhanToggle');adhan.checked=localStorage.getItem('oyya_adhan')==='1';adhan.onchange=()=>{localStorage.setItem('oyya_adhan',adhan.checked?'1':'0');meta.textContent=adhan.checked?'الأذان مفعّل':'الأذان متوقف'};let ctx=null,gain=null,timer=null,on=false,i=0;const seq=[220,261.63,329.63,392,329.63,261.63];function note(){const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=seq[i++%seq.length];o.type='sine';g.gain.setValueAtTime(.001,ctx.currentTime);g.gain.linearRampToValueAtTime(.07,ctx.currentTime+.05);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.8);o.connect(g);g.connect(gain);o.start();o.stop(ctx.currentTime+.85)}async function start(){ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();gain=gain||ctx.createGain();if(!gain._x){gain.connect(ctx.destination);gain._x=1}gain.gain.value=Number(vol.value);note();timer=setInterval(note,850);on=true;rb.textContent='❚❚';dock.classList.remove('off');meta.textContent='OYYA Radio · بث تجريبي'}function stop(){clearInterval(timer);timer=null;on=false;rb.textContent='▶';dock.classList.add('off');meta.textContent='متوقف'}rb.onclick=()=>on?stop():start();vol.oninput=()=>{if(gain)gain.gain.value=Number(vol.value)}}
</script></body></html>